{
  "rules": [
    {
      "rule_id": "R001",
      "when": {
        "all": [
          {
            "fact": "w2_employer_count",
            "gte": 1
          }
        ]
      },
      "document": "Form W-2 from each employer",
      "count_from": "w2_employer_count",
      "client_reason": "You were paid wages, so we need the year-end wage statement from each employer, including any job you left.",
      "source_url": "https://www.irs.gov/taxtopics/tc401",
      "source_title": "Topic no. 401, Wages and salaries",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "R002",
      "when": {
        "all": [
          {
            "fact": "self_employment",
            "eq": true
          }
        ]
      },
      "document": "Business income and expense records, including any Forms 1099-NEC",
      "count_from": null,
      "client_reason": "You had freelance or business income, so we need your income and expense records and any year-end payment statements from clients.",
      "source_url": "https://www.irs.gov/businesses/small-businesses-self-employed/manage-taxes-for-your-gig-work",
      "source_title": "Manage taxes for your gig work",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "R003",
      "when": {
        "all": [
          {
            "fact": "business_app_payments",
            "eq": true
          }
        ]
      },
      "document": "Any Form 1099-K received",
      "count_from": null,
      "client_reason": "Customers paid you through an app or online marketplace, so we need any year-end statement it sent you.",
      "source_url": "https://www.irs.gov/businesses/understanding-your-form-1099-k",
      "source_title": "Understanding your Form 1099-K",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "R004",
      "when": {
        "all": [
          {
            "fact": "interest_income",
            "eq": true
          }
        ]
      },
      "document": "Form 1099-INT from each payer",
      "count_from": null,
      "client_reason": "You earned interest, so we need the year-end interest statement from each bank or payer.",
      "source_url": "https://www.irs.gov/taxtopics/tc403",
      "source_title": "Topic no. 403, Interest received",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "R005",
      "when": {
        "all": [
          {
            "fact": "dividend_income",
            "eq": true
          }
        ]
      },
      "document": "Form 1099-DIV from each payer",
      "count_from": null,
      "client_reason": "You received dividends, so we need the year-end dividend statement from each payer.",
      "source_url": "https://www.irs.gov/taxtopics/tc404",
      "source_title": "Topic no. 404, Dividends",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "R006",
      "when": {
        "all": [
          {
            "fact": "sold_investments",
            "eq": true
          }
        ]
      },
      "document": "Form 1099-B or the consolidated brokerage statement",
      "count_from": null,
      "client_reason": "You sold investments, so we need the year-end statement from your brokerage.",
      "source_url": "https://www.irs.gov/publications/p550",
      "source_title": "Publication 550 (2025), Investment Income and Expenses",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "R007",
      "when": {
        "all": [
          {
            "fact": "digital_asset_transactions",
            "eq": true
          }
        ]
      },
      "document": "Form 1099-DA if received, plus transaction records",
      "count_from": null,
      "client_reason": "You sold or traded digital assets, so we need any year-end statement from the platform and your own transaction records.",
      "source_url": "https://www.irs.gov/filing/digital-assets",
      "source_title": "Digital assets (IRS.gov)",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "R008",
      "when": {
        "all": [
          {
            "fact": "retirement_distribution",
            "eq": true
          }
        ]
      },
      "document": "Form 1099-R",
      "count_from": null,
      "client_reason": "You took money out of a retirement account or rolled one over, so we need the year-end distribution statement.",
      "source_url": "https://www.irs.gov/instructions/i1099r",
      "source_title": "Instructions for Forms 1099-R and 5498 (2026)",
      "source_version": "final_instructions",
      "status": "to_verify"
    },
    {
      "rule_id": "R009",
      "when": {
        "all": [
          {
            "fact": "social_security",
            "eq": true
          }
        ]
      },
      "document": "Form SSA-1099",
      "count_from": null,
      "client_reason": "You received Social Security, so we need the yearly benefit statement.",
      "source_url": "https://www.irs.gov/taxtopics/tc423",
      "source_title": "Topic no. 423, Social Security and equivalent railroad retirement benefits",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "R010",
      "when": {
        "all": [
          {
            "fact": "unemployment",
            "eq": true
          }
        ]
      },
      "document": "Form 1099-G",
      "count_from": null,
      "client_reason": "You received unemployment benefits, so we need the year-end statement from the state.",
      "source_url": "https://www.irs.gov/taxtopics/tc418",
      "source_title": "Topic no. 418, Unemployment compensation",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "R011",
      "when": {
        "all": [
          {
            "fact": "state_refund_received",
            "eq": true
          },
          {
            "fact": "itemized_last_year",
            "eq": true
          }
        ]
      },
      "document": "Form 1099-G for the refund",
      "count_from": null,
      "client_reason": "You got a state or local tax refund after itemizing last year, so we need the statement showing the refund.",
      "source_url": "https://www.irs.gov/faqs/interest-dividends-other-types-of-income/1099-information-returns-all-other/1099-information-returns-all-other",
      "source_title": "1099 Information Returns (All Other) (IRS FAQ: I received a Form 1099-G reporting the state tax refund I received during the year)",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "R012",
      "when": {
        "all": [
          {
            "fact": "marketplace_coverage",
            "eq": true
          }
        ]
      },
      "document": "Form 1095-A, Health Insurance Marketplace Statement",
      "count_from": null,
      "client_reason": "You had a Marketplace plan, so we need the statement the Marketplace sends.",
      "source_url": "https://www.irs.gov/individuals/reconciling-your-advance-payments-of-the-premium-tax-credit",
      "source_title": "Reconciling your advance payments of the Premium Tax Credit",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "R013",
      "when": {
        "all": [
          {
            "fact": "hsa_withdrawal",
            "eq": true
          }
        ]
      },
      "document": "Form 1099-SA",
      "count_from": null,
      "client_reason": "You took money out of your health savings account, so we need the year-end distribution statement.",
      "source_url": "https://www.irs.gov/instructions/i1099sa",
      "source_title": "Instructions for Forms 1099-SA and 5498-SA (12/2026)",
      "source_version": "final_instructions",
      "status": "to_verify"
    },
    {
      "rule_id": "R014",
      "when": {
        "all": [
          {
            "fact": "has_mortgage",
            "eq": true
          }
        ]
      },
      "document": "Form 1098",
      "count_from": null,
      "client_reason": "You have a mortgage, so we need the year-end mortgage interest statement from your lender.",
      "source_url": "https://www.irs.gov/instructions/i1098",
      "source_title": "Instructions for Form 1098 (12/2026)",
      "source_version": "final_instructions",
      "status": "to_verify"
    },
    {
      "rule_id": "R015",
      "when": {
        "all": [
          {
            "fact": "bought_home",
            "eq": true
          }
        ]
      },
      "document": "Closing statement",
      "count_from": null,
      "client_reason": "You bought a home, so we need the closing statement from the purchase.",
      "source_url": "https://www.irs.gov/publications/p530",
      "source_title": "Publication 530 (2025), Tax Information for Homeowners",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "R016",
      "when": {
        "all": [
          {
            "fact": "student_loan_interest",
            "eq": true
          }
        ]
      },
      "document": "Form 1098-E",
      "count_from": null,
      "client_reason": "You paid student loan interest, so we need the year-end interest statement from your loan servicer.",
      "source_url": "https://www.irs.gov/taxtopics/tc456",
      "source_title": "Topic no. 456, Student loan interest deduction",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "R017",
      "when": {
        "all": [
          {
            "fact": "tuition_paid",
            "eq": true
          }
        ]
      },
      "document": "Form 1098-T",
      "count_from": null,
      "client_reason": "You paid college tuition, so we need the tuition statement from the school.",
      "source_url": "https://www.irs.gov/credits-deductions/individuals/education-credits-aotc-llc",
      "source_title": "Education credits: AOTC and LLC",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "R018",
      "when": {
        "all": [
          {
            "fact": "dependent_care_paid",
            "eq": true
          }
        ]
      },
      "document": "Provider name, address, taxpayer ID, and amount paid",
      "count_from": null,
      "client_reason": "You paid for care, so we need each provider's name, address, taxpayer ID number, and how much you paid.",
      "source_url": "https://www.irs.gov/pub/irs-dft/i2441--dft.pdf",
      "source_title": "2026 Instructions for Form 2441, Child and Dependent Care Expenses (draft, August 21, 2026)",
      "source_version": "draft_instructions",
      "status": "to_verify"
    },
    {
      "rule_id": "R019",
      "when": {
        "all": [
          {
            "fact": "new_dependent",
            "eq": true
          }
        ]
      },
      "document": "The dependent's Social Security number and date of birth",
      "count_from": null,
      "client_reason": "You have a new dependent, so we need a copy of their Social Security card and their date of birth.",
      "source_url": "https://www.irs.gov/individuals/checklist-for-free-tax-return-preparation",
      "source_title": "Checklist for free tax return preparation",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "R020",
      "when": {
        "all": [
          {
            "fact": "k1_count",
            "gte": 1
          }
        ]
      },
      "document": "Schedule K-1 from each",
      "count_from": "k1_count",
      "client_reason": "You have a share in a partnership, company, estate, or trust, so we need the year-end statement from each one.",
      "source_url": "https://www.irs.gov/pub/irs-dft/i1040se--dft.pdf",
      "source_title": "2026 Instructions for Schedule E (Form 1040), Supplemental Income and Loss (early release draft, posted 09/24/2026)",
      "source_version": "draft_instructions",
      "status": "to_verify"
    },
    {
      "rule_id": "R021",
      "when": {
        "all": [
          {
            "fact": "rental_property",
            "eq": true
          }
        ]
      },
      "document": "Rental income and expense records",
      "count_from": null,
      "client_reason": "You rented out a home, a room, or other real estate, so we need your rental income and expense records.",
      "source_url": "https://www.irs.gov/pub/irs-dft/i1040se--dft.pdf",
      "source_title": "2026 Instructions for Schedule E (Form 1040), Supplemental Income and Loss (draft, September 2026)",
      "source_version": "draft_instructions",
      "status": "to_verify"
    },
    {
      "rule_id": "R022",
      "when": {
        "all": [
          {
            "fact": "estimated_payments_made",
            "eq": true
          }
        ]
      },
      "document": "Dates and amounts paid",
      "count_from": null,
      "client_reason": "You made estimated tax payments, so we need the date and amount of each payment.",
      "source_url": "https://www.irs.gov/pub/irs-prior/f1040es--2026.pdf",
      "source_title": "Form 1040-ES (2026), Estimated Tax for Individuals (Record of Estimated Tax Payments)",
      "source_version": "final_instructions",
      "status": "to_verify"
    },
    {
      "rule_id": "R023",
      "when": {
        "all": [
          {
            "fact": "gambling_winnings",
            "eq": true
          }
        ]
      },
      "document": "Form W-2G if received",
      "count_from": null,
      "client_reason": "You had gambling winnings, so we need any winnings statement the payer gave you.",
      "source_url": "https://www.irs.gov/taxtopics/tc419",
      "source_title": "Topic no. 419, Gambling income and losses",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "R024",
      "when": {
        "all": [
          {
            "fact": "ip_pin_enrolled",
            "eq": true
          }
        ]
      },
      "document": "This year's IP PIN",
      "count_from": null,
      "client_reason": "You're in the IRS identity protection program, so we need this year's six-digit PIN.",
      "source_url": "https://www.irs.gov/identity-theft-fraud-scams/frequently-asked-questions-about-the-identity-protection-personal-identification-number-ip-pin",
      "source_title": "Frequently asked questions about the identity protection personal identification number (IP PIN)",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "R025",
      "when": {
        "all": [
          {
            "fact": "charitable_giving",
            "eq": true
          }
        ]
      },
      "document": "Receipts and written acknowledgments",
      "count_from": null,
      "client_reason": "You gave to charity, so we need your receipts and the written acknowledgments from the charities.",
      "source_url": "https://www.irs.gov/taxtopics/tc506",
      "source_title": "Topic no. 506, Charitable contributions",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "R026",
      "when": {
        "all": [
          {
            "fact": "tips_income",
            "eq": true
          }
        ]
      },
      "document": "Tip records and how the employer reported them",
      "count_from": null,
      "client_reason": "You earned tips, so we need your tip records and how your employer reported them.",
      "source_url": "https://www.irs.gov/newsroom/treasury-irs-issue-final-regulations-listing-occupations-where-workers-customarily-and-regularly-receive-tips-under-the-one-big-beautiful-bill",
      "source_title": "Treasury, IRS issue final regulations listing occupations where workers customarily and regularly receive tips under the One, Big, Beautiful Bill (IR-2026-49, April 10, 2026)",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "R027",
      "when": {
        "all": [
          {
            "fact": "overtime_pay",
            "eq": true
          }
        ]
      },
      "document": "Overtime records and how the employer reported them",
      "count_from": null,
      "client_reason": "You were paid overtime, so we need your overtime records and how your employer reported them.",
      "source_url": "https://www.irs.gov/pub/taxpros/fs-2026-13.pdf",
      "source_title": "Updates to questions and answers about the new deduction for qualified overtime compensation (FS-2026-13, August 2026; announced in IR-2026-88)",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "R028",
      "when": {
        "all": [
          {
            "fact": "new_vehicle_loan",
            "eq": true
          }
        ]
      },
      "document": "Lender's interest statement",
      "count_from": null,
      "client_reason": "You paid interest on a loan for a new vehicle, so we need the lender's statement of interest paid.",
      "source_url": "https://www.irs.gov/instructions/i1098vli",
      "source_title": "Instructions for Form 1098-VLI (Rev. December 2026), for calendar year 2026",
      "source_version": "final_instructions",
      "status": "to_verify"
    },
    {
      "rule_id": "R029",
      "when": {
        "all": [
          {
            "fact": "hsa_direct_contribution",
            "eq": true
          }
        ]
      },
      "document": "Contribution records, plus Form 5498-SA if received",
      "count_from": null,
      "client_reason": "You, or someone else for you, put money into your health savings account outside your paycheck, so we need your contribution records and any year-end contribution statement, which may not arrive until the end of May.",
      "source_url": "https://www.irs.gov/instructions/i1099sa",
      "source_title": "Instructions for Forms 1099-SA and 5498-SA (12/2026)",
      "source_version": "final_instructions",
      "status": "to_verify"
    },
    {
      "rule_id": "R030",
      "when": {
        "all": [
          {
            "fact": "sold_home",
            "eq": true
          }
        ]
      },
      "document": "Closing statement, plus Form 1099-S if received",
      "count_from": null,
      "client_reason": "You sold a home, so we need the closing statement and any sale statement you received.",
      "source_url": "https://www.irs.gov/publications/p523",
      "source_title": "Publication 523 (2025), Selling Your Home",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "T001",
      "when": {
        "all": [
          {
            "fact": "clean_energy_installed",
            "eq": true
          },
          {
            "fact": "clean_energy_install_year",
            "eq": 2026
          }
        ]
      },
      "document": "No document needed: this credit ended",
      "count_from": null,
      "source_url": "https://www.irs.gov/newsroom/faqs-for-modification-of-sections-25c-25d-25e-30c-30d-45l-45w-and-179d-under-public-law-119-21-139-stat-72-july-4-2025-commonly-known-as-the-one-big-beautiful-bill-obbb",
      "source_title": "IRS FS-2025-05, FAQs for modification of sections 25C, 25D, 25E, 30C, 30D, 45L, 45W, and 179D under Public Law 119-21",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "T002",
      "when": {
        "all": [
          {
            "fact": "efficiency_improvements",
            "eq": true
          },
          {
            "fact": "efficiency_improvements_year",
            "eq": 2026
          }
        ]
      },
      "document": "No document needed: this credit ended",
      "count_from": null,
      "source_url": "https://www.irs.gov/newsroom/faqs-for-modification-of-sections-25c-25d-25e-30c-30d-45l-45w-and-179d-under-public-law-119-21-139-stat-72-july-4-2025-commonly-known-as-the-one-big-beautiful-bill-obbb",
      "source_title": "IRS FS-2025-05, FAQs for modification of sections 25C, 25D, 25E, 30C, 30D, 45L, 45W, and 179D under Public Law 119-21",
      "source_version": "guidance",
      "status": "to_verify"
    },
    {
      "rule_id": "T003",
      "when": {
        "all": [
          {
            "fact": "ev_purchased",
            "eq": true
          },
          {
            "fact": "ev_acquired_date",
            "gte": "2026-01-01"
          },
          {
            "fact": "ev_acquired_date",
            "lte": "2026-12-31"
          }
        ]
      },
      "document": "No document needed: this credit ended",
      "count_from": null,
      "source_url": "https://www.irs.gov/newsroom/faqs-for-modification-of-sections-25c-25d-25e-30c-30d-45l-45w-and-179d-under-public-law-119-21-139-stat-72-july-4-2025-commonly-known-as-the-one-big-beautiful-bill-obbb",
      "source_title": "IRS FS-2025-05, FAQs for modification of sections 25C, 25D, 25E, 30C, 30D, 45L, 45W, and 179D under Public Law 119-21",
      "source_version": "guidance",
      "status": "to_verify"
    }
  ]
}

